# ==============================================================================
# Project 06: Clinical Dataset Engineering for Pharmacometrics
# Script: 04_qc_nm_dataset.R - Independent QC of NONMEM dataset
# ==============================================================================
#
# This script performs INDEPENDENT quality control on the NONMEM dataset
# generated by 02_build_nm_dataset.R. It does NOT share code with the
# build script - all checks are written independently.
#
# QC deliverables:
#   1. Scripted checks (pass/fail checklist)
#   2. Subject-level spot audit (random sampling)
#   3. QC log (findings + resolution documentation)
# ==============================================================================

source("R/00_setup.R")
source("R/utils/check_functions.R")

# ---- 1. Load dataset for QC ----
cat("=== INDEPENDENT QC OF NONMEM DATASET ===\n\n")

nm_data <- read_csv(file.path(paths$outputs, "nm_dataset.csv"),
                    show_col_types = FALSE, na = ".")

cat(sprintf("Dataset loaded: %d records, %d variables, %d subjects\n",
            nrow(nm_data), ncol(nm_data), n_distinct(nm_data$ID)))

# ---- 2. Run automated QC checks ----
cat("\n--- Automated QC Checks ---\n")

qc_results <- run_all_qc_checks(nm_data, config)

# Print results
for (i in seq_len(nrow(qc_results))) {
  status_symbol <- switch(qc_results$status[i],
    "PASS"    = "[PASS]",
    "FAIL"    = "[FAIL]",
    "WARNING" = "[WARN]",
    "INFO"    = "[INFO]",
    "SKIP"    = "[SKIP]"
  )
  cat(sprintf("  %s %s: %s\n",
              status_symbol, qc_results$check_name[i], qc_results$details[i]))
}

# ---- 3. Subject-level spot audit ----
cat("\n--- Subject-Level Spot Audit ---\n")
audit <- spot_audit(nm_data, n_subjects = 5, seed = 42)

# Print audit summary per subject
for (sid in audit$subject_ids) {
  subj_data <- audit$data %>% filter(ID == sid)
  cat(sprintf("\n  Subject %d:\n", sid))
  cat(sprintf("    Dose records: %d\n", sum(subj_data$EVID == 1)))
  cat(sprintf("    Observations: %d\n", sum(subj_data$EVID == 0)))
  cat(sprintf("    Time range: %.1f - %.1f hours\n",
              min(subj_data$TIME), max(subj_data$TIME)))
  cat(sprintf("    BLQ observations: %d\n", sum(subj_data$BLQ == 1, na.rm = TRUE)))

  # Check dose-obs ordering (pre-dose samples are expected baseline PK)
  first_obs_time <- min(subj_data$TIME[subj_data$EVID == 0], na.rm = TRUE)
  first_dose_time <- min(subj_data$TIME[subj_data$EVID == 1], na.rm = TRUE)
  if (first_obs_time < first_dose_time) {
    if (first_obs_time >= -24) {
      cat("    [OK] Pre-dose sample present (expected baseline PK)\n")
    } else {
      cat("    [WARN] Observation >24h before first dose\n")
    }
  } else {
    cat("    [OK] First dose precedes first observation\n")
  }
}

# ---- 4. Cross-check against source SDTM ----
cat("\n--- Cross-check vs Source SDTM ---\n")

dm_source <- read_csv(file.path(paths$sdtm, "dm.csv"), show_col_types = FALSE)
pc_source <- read_csv(file.path(paths$sdtm, "pc.csv"), show_col_types = FALSE)
ex_source <- read_csv(file.path(paths$sdtm, "ex.csv"), show_col_types = FALSE)

cat(sprintf("  Source subjects (DM): %d | Dataset subjects: %d\n",
            n_distinct(dm_source$USUBJID), n_distinct(nm_data$ID)))
cat(sprintf("  Source PK records (PC): %d | Dataset observations: %d\n",
            nrow(pc_source), sum(nm_data$EVID == 0)))
cat(sprintf("  Source dose records (EX): %d | Dataset doses: %d\n",
            nrow(ex_source), sum(nm_data$EVID == 1)))

# ---- 5. Save QC results ----
cat("\n--- Saving QC Outputs ---\n")

# Save checklist
write_csv(qc_results, file.path(paths$outputs, "qc_checklist.csv"))

# Save QC log
qc_log <- tibble(
  timestamp     = Sys.time(),
  qc_analyst    = "H. Besbassi",
  dataset       = "nm_dataset.csv",
  n_checks      = nrow(qc_results),
  n_pass        = sum(qc_results$status == "PASS"),
  n_fail        = sum(qc_results$status == "FAIL"),
  n_warning     = sum(qc_results$status == "WARNING"),
  spot_audit_n  = audit$n_checked,
  spot_audit_seed = audit$seed,
  overall_status = if_else(sum(qc_results$status == "FAIL") == 0, "QC PASS", "QC FAIL"),
  notes         = "Independent QC performed on NONMEM analysis dataset"
)

write_csv(qc_log, file.path(paths$outputs, "qc_log.csv"))

cat(sprintf("\nOverall QC status: %s\n", qc_log$overall_status))
cat(sprintf("Results saved to: %s\n", paths$outputs))
